import raw from "./static-snapshot.json";
import type {
  BoroughAggregate,
  BoroughDetailResponse,
  CityKey,
  RecentInterventionRecord,
  StaticSnapshot,
} from "@/lib/types";

// Generated by `pnpm export:snapshot` from a database built with the data
// pipeline (see README). JSON literal types don't narrow to the unions in
// StaticSnapshot, hence the cast.
const SNAPSHOT = raw as unknown as StaticSnapshot;

/** Lets Vercel's CDN absorb repeat requests: the data only changes on redeploy. */
export const SNAPSHOT_CACHE_HEADERS = {
  "Cache-Control": "public, s-maxage=86400, stale-while-revalidate=604800",
};

export function snapshotGeneratedAt(): string | null {
  return SNAPSHOT.generatedAt;
}

export function snapshotBoroughs(city: CityKey): BoroughAggregate[] {
  return SNAPSHOT.cities[city]?.boroughs ?? [];
}

export function snapshotBoroughDetail(
  city: CityKey,
  borough: string,
): BoroughDetailResponse | null {
  return SNAPSHOT.cities[city]?.details[borough] ?? null;
}

export function snapshotRecentInterventions(city: CityKey): RecentInterventionRecord[] {
  return SNAPSHOT.cities[city]?.recentInterventions ?? [];
}
